    [RelayCommand] private async Task SaveAsync(CancellationToken ct) { ErrorMessage = string.Empty; if (!TryType(DiscountType, out var type) || !decimal.TryParse(Percentage, out var pct) || !decimal.TryParse(FixedAmount, out var amount) || !decimal.TryParse(MaximumDiscount, out var max) || !int.TryParse(ApprovalLevel, out var level) || !DateTime.TryParse(EffectiveFrom, out var from) || !DateTime.TryParse(EffectiveTo, out var to)) { ErrorMessage = "Loại, mức giảm, cấp duyệt hoặc hiệu lực không hợp lệ."; RaiseState(); return; } try { Result<HotelDiscountPolicyDto> result; if (SelectedItem is null) { if (_create is null) { ErrorMessage = "Chưa đăng ký command cấu hình thật."; return; } result = await _create.HandleAsync(new CreateHotelDiscountPolicyCommand(Code, Name, type, pct, amount, max, AllowedRoles, level, ReasonRequired, NullIfEmpty(AccountingTreatment), from, to, NullIfEmpty(Description)), ct); } else { if (_update is null) { ErrorMessage = "Chưa đăng ký command cấu hình thật."; return; } result = await _update.HandleAsync(new UpdateHotelDiscountPolicyCommand(SelectedItem.HotelDiscountPolicyId, Code, Name, type, pct, amount, max, AllowedRoles, level, ReasonRequired, NullIfEmpty(AccountingTreatment), from, to, NullIfEmpty(Description), SelectedItem.RowVersion ?? []), ct); } if (result.IsFailure) { ErrorMessage = result.Error?.Message ?? "Không lưu được cấu hình."; return; } InfoMessage = "Đã lưu chính sách chiết khấu vào dữ liệu thật."; IsEditing = false; await LoadAsync(ct); } catch (Exception ex) { ErrorMessage = $"Không lưu được cấu hình: {ex.Message}"; } finally { RaiseState(); } }
