    private void Fill(HotelDiscountPolicyDto x) { DiscountType = TypeLabel(x.DiscountType); Code = x.Code; Name = x.Name; Percentage = x.Percentage.ToString("0.####"); FixedAmount = x.FixedAmount.ToString("0.##"); MaximumDiscount = x.MaximumDiscount.ToString("0.##"); AllowedRoles = x.AllowedRoles; ApprovalLevel = x.ApprovalLevel.ToString(); ReasonRequired = x.ReasonRequired; AccountingTreatment = x.AccountingTreatment ?? string.Empty; EffectiveFrom = x.EffectiveFrom.ToString("yyyy-MM-dd"); EffectiveTo = x.EffectiveTo.ToString("yyyy-MM-dd"); Description = x.Description ?? string.Empty; }
    private static bool TryType(string value, out HotelDiscountType type) { type = value switch { "Số tiền cố định" => HotelDiscountType.FixedAmount, "Miễn phí" => HotelDiscountType.Complimentary, _ => HotelDiscountType.Percentage }; return value is not ""; } private static string TypeLabel(HotelDiscountType type) => type switch { HotelDiscountType.FixedAmount => "Số tiền cố định", HotelDiscountType.Complimentary => "Miễn phí", _ => "Phần trăm" }; private static string? NullIfEmpty(string value) => string.IsNullOrWhiteSpace(value) ? null : value.Trim(); private static Result<HotelDiscountPolicyDto> Missing() => Result<HotelDiscountPolicyDto>.Failure(Error.System("HOTEL_DISCOUNT_COMMAND_MISSING", "Command is unavailable.")); private void RaiseState() { OnPropertyChanged(nameof(HasError)); OnPropertyChanged(nameof(HasInfo)); OnPropertyChanged(nameof(IsReadOnlyPanelVisible)); OnPropertyChanged(nameof(SelectedSummary)); OnPropertyChanged(nameof(SelectedStatus)); OnPropertyChanged(nameof(SelectedTypeLabel)); } partial void OnSelectedItemChanged(HotelDiscountPolicyDto? value) { if (!IsEditing && value is not null) Fill(value); RaiseState(); }
